UTF8_AVX512_TARGET static bool validate_avx512(const unsigned char *bytes,
                                                size_t length) {
  size_t index = 0;

  // Align to a code-point boundary and leave three bytes of safe history.
  while (index < 3 && index < length) {
    if (!decode_one(bytes, length, index)) {
      return false;
    }
  }
  if (index < 3) {
    return validate_scalar(bytes, length);
  }

  while (length - index >= 64) {
    const __m512i current = _mm512_loadu_si512(bytes + index);

    // Skip all-ASCII blocks before history loads and structural checks.
    if (_mm512_movepi8_mask(current) == 0) {
      if (pending_sequence_start(bytes, index) < index) {
        return false;
      }
      index += 64;
      continue;
    }

    const __m512i previous1 = _mm512_loadu_si512(bytes + index - 1);
    const __m512i previous2 = _mm512_loadu_si512(bytes + index - 2);
    const __m512i previous3 = _mm512_loadu_si512(bytes + index - 3);

    const __mmask64 continuation = avx512_is_continuation(current);
    const __mmask64 expected_continuation =
        avx512_is_lead2(previous1) |
        (avx512_is_lead3(previous1) | avx512_is_lead4(previous1)) |
        ((avx512_is_lead3(previous2) | avx512_is_lead4(previous2)) |
         avx512_is_lead4(previous3));

    const __mmask64 special_e0 =
        _mm512_cmpeq_epi8_mask(previous1, avx512_byte(0xE0)) &
        avx512_u8_lt(current, avx512_byte(0xA0));
    const __mmask64 special_ed =
        _mm512_cmpeq_epi8_mask(previous1, avx512_byte(0xED)) &
        avx512_u8_gt(current, avx512_byte(0x9F));
    const __mmask64 special_f0 =
        _mm512_cmpeq_epi8_mask(previous1, avx512_byte(0xF0)) &
        avx512_u8_lt(current, avx512_byte(0x90));
    const __mmask64 special_f4 =
        _mm512_cmpeq_epi8_mask(previous1, avx512_byte(0xF4)) &
        avx512_u8_gt(current, avx512_byte(0x8F));

    const __mmask64 bad =
        (continuation ^ expected_continuation) |
        avx512_is_invalid_start(current) | special_e0 | special_ed |
        special_f0 | special_f4;
    if (bad != 0) {
      return false;
    }

    index += 64;
  }

  // Restart at an unfinished lead so the scalar suffix checks crossings and
  // the exact end of input without reading beyond it.
  size_t tail = pending_sequence_start(bytes, index);
  while (tail < length) {
    if (!decode_one(bytes, length, tail)) {
      return false;
    }
  }
  return true;
}
